-- Schema: Star Schema

-- Fact Table: sensor_readings
CREATE TABLE sensor_readings (
    reading_id BIGINT PRIMARY KEY,
    device_id VARCHAR(255) NOT NULL,
    time_id TIMESTAMP NOT NULL,
    temperature DECIMAL(5,2),
    humidity DECIMAL(5,2),
    status VARCHAR(255)
);

-- Dimension Table: device
CREATE TABLE device (
    device_id VARCHAR(255) PRIMARY KEY,
    device_name VARCHAR(255),
    location_id INT,
    manufacturer VARCHAR(255)
);

-- Dimension Table: time
CREATE TABLE time (
    time_id TIMESTAMP PRIMARY KEY,
    hour INT,
    day INT,
    month INT,
    year INT,
    day_of_week INT
);

-- Dimension Table: location
CREATE TABLE location (
    location_id INT PRIMARY KEY,
    location_name VARCHAR(255),
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6)
);

-- Partitioning Strategy for sensor_readings (Fact Table)
-- Partition by time (monthly or quarterly) to align with common aggregation periods.
-- Partitioning Key: time_id

-- Indexing Strategy for Dimension Tables
-- device: Index on device_id (primary key) and location_id
CREATE INDEX idx_device_location_id ON device (location_id);

-- time: Index on time_id (primary key) and hour, day, month, year, day_of_week
CREATE INDEX idx_time_hour ON time (hour);
CREATE INDEX idx_time_day ON time (day);
CREATE INDEX idx_time_month ON time (month);
CREATE INDEX idx_time_year ON time (year);
CREATE INDEX idx_time_day_of_week ON time (day_of_week);

-- location: Index on location_id (primary key)
CREATE INDEX idx_location_location_id ON location (location_id);
